script:
class Component extends DCLogic {
state = { data: [], sel: '', tab: 'all', q: '', adjAmt: '', adjWhy: '', adjMsg: '', resetPassword: '', resetShown: false };
mount() { this.refresh(); }
refresh(select) {
parent.SONNA_API('GET', '/api/admin/users').then((r) => {
if (r._status !== 200) return this.setState({ adjMsg: r.error || 'Không tải được danh sách khách hàng.' });
this.setState({ data: r.users || [], sel: select || this.state.sel || ((r.users || [])[0] || {}).id || '', adjMsg: '' });
}).catch(() => this.setState({ adjMsg: 'Lỗi kết nối máy chủ.' }));
}
adjust(sign) {
const user = (this.state.data || []).find((u) => String(u.id) === String(this.state.sel));
const amount = parseInt(String(this.state.adjAmt).replace(/\D/g, ''), 10) || 0;
if (!user || !amount || !this.state.adjWhy.trim()) return this.setState({ adjMsg: 'Chọn khách, nhập số tiền và lý do.' });
parent.SONNA_API('POST', '/api/admin/users/' + user.id + '/wallet', { delta: sign * amount, reason: this.state.adjWhy.trim() }).then((r) => {
if (r._status !== 200) return this.setState({ adjMsg: r.error || 'Không cập nhật được ví.' });
this.setState({ adjAmt: '', adjWhy: '', adjMsg: 'Đã cập nhật số dư ví.' }); this.refresh(user.id);
}).catch(() => this.setState({ adjMsg: 'Lỗi kết nối máy chủ.' }));
}
resetCustomerPassword() {
const user = (this.state.data || []).find((u) => String(u.id) === String(this.state.sel));
const password = this.state.resetPassword || '';
if (!user || password.length < 6 || password.length > 100) return this.setState({ adjMsg: 'Mật khẩu mới cần từ 6 đến 100 ký tự.' });
parent.SONNA_API('POST', '/api/admin/users/' + user.id + '/password', { password }).then((r) => {
if (r._status !== 200) return this.setState({ adjMsg: r.error || 'Không đặt lại được mật khẩu.' });
this.setState({ adjMsg: 'Mật khẩu mới đã được đặt. Hãy gửi cho khách qua kênh riêng.' });
}).catch((error) => { console.error('[SONNA] Không thể đặt lại mật khẩu:', error); this.setState({ adjMsg: 'Lỗi kết nối máy chủ.' }); });
}
lock() {
const user = (this.state.data || []).find((u) => String(u.id) === String(this.state.sel));
if (!user) return;
parent.SONNA_API('POST', '/api/admin/users/' + user.id + '/lock', { locked: !user.locked }).then((r) => {
if (r._status !== 200) return this.setState({ adjMsg: r.error || 'Không đổi được trạng thái tài khoản.' });
this.refresh(user.id);
}).catch(() => this.setState({ adjMsg: 'Lỗi kết nối máy chủ.' }));
}
renderVals() {
const st = this.state, data = st.data || [], on = '#FF8A1F', off = '#A3ACC4', ok = '#43D9A0', bad = '#FF6B7A';
const fmt = (n) => String(Number(n) || 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '\u20ab';
const date = (s) => s ? new Date(s).toLocaleDateString('vi-VN') : '?';
const nav = [{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' }, { label: 'Quản lý acc', href: 'AdminAccounts.dc.html' }, { label: 'Đơn hàng', href: 'AdminOrders.dc.html' }, { label: 'Thanh toán', href: 'AdminPayments.dc.html' }, { label: 'Người dùng', href: 'AdminUsers.dc.html', active: true }, { label: 'Khuyến mãi', href: 'AdminPromos.dc.html' }, { label: 'Nội dung website', href: 'AdminContent.dc.html' }, { label: 'Báo cáo', href: '#bao-cao' }, { label: 'Phân quyền', href: 'AdminRoles.dc.html' }, { label: 'Nhật ký hoạt động', href: '#nhat-ky' }].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));
const norm = (s) => String(s || '').toLowerCase();
const q = norm(st.q).trim();
const matches = data.filter((u) => (st.tab === 'all' || (st.tab === 'active' && !u.locked) || (st.tab === 'locked' && u.locked) || (st.tab === 'wallet' && u.wallet > 0)) && (!q || norm(u.username).includes(q) || String(u.id).includes(q)));
const rows = matches.map((u) => ({ id: 'KH-' + String(u.id).padStart(4, '0'), name: u.username, joined: date(u.createdAt), wallet: fmt(u.wallet), bought: String(u.orderCount || 0), spent: fmt(u.spent), status: u.locked ? 'Bị khóa' : 'Hoạt động', col: u.locked ? bad : ok, bg: String(u.id) === String(st.sel) ? '#1F2538' : 'transparent', pick: () => this.setState({ sel: u.id, resetPassword: '', resetShown: false, adjMsg: '' }) }));
const tabs = [{ id: 'all', label: 'Tất cả', count: data.length }, { id: 'active', label: 'Hoạt động', count: data.filter(u => !u.locked).length }, { id: 'locked', label: 'Bị khóa', count: data.filter(u => u.locked).length }, { id: 'wallet', label: 'Có số dư ví', count: data.filter(u => u.wallet > 0).length }].map((t) => ({ ...t, pick: () => this.setState({ tab: t.id }), line: t.id === st.tab ? on : 'transparent', fg: t.id === st.tab ? '#EAEFFA' : off }));
const cur = data.find((u) => String(u.id) === String(st.sel)) || data[0];
const sel = cur ? { id: 'KH-' + String(cur.id).padStart(4, '0'), loginId: cur.username, name: cur.username, contact: cur.username, status: cur.locked ? 'Bị khóa' : 'Hoạt động', col: cur.locked ? bad : ok, stats: [{ k: 'Số dư ví', v: fmt(cur.wallet) }, { k: 'Tổng đã nạp', v: fmt(cur.toppedUp) }, { k: 'Đã mua', v: (cur.orderCount || 0) + ' đơn' }, { k: 'Tổng chi', v: fmt(cur.spent) }], recent: cur.recent || [], transactions: (cur.transactions || []).map((x) => ({ id: x.id, time: x.time || '-', title: x.title || 'Giao d\u1ecbch', status: x.status || '', amount: (Number(x.amount) < 0 ? '-' : '+') + fmt(Math.abs(Number(x.amount) || 0)), amountCol: Number(x.amount) < 0 ? bad : ok, hasAccounts: Array.isArray(x.accounts) && x.accounts.length > 0, accountLines: (x.accounts || []).map((a) => (a.tag ? a.tag + ': ' : '') + a.line).join('\n') })), noTransactions: !(cur.transactions || []).length, lockLabel: cur.locked ? 'Mở khóa tài khoản' : 'Khóa tài khoản', lockCol: cur.locked ? ok : bad } : { id: '?', loginId: '?', name: 'Chưa có khách hàng', contact: '?', status: '?', col: off, stats: [], recent: [], transactions: [], noTransactions: true, lockLabel: 'Khóa tài khoản', lockCol: off };
return { nav, tabs, rows, sel, q: st.q, onQuery: (e) => this.setState({ q: e.target.value }), noRows: rows.length === 0, footerText: 'Hiển thị ' + rows.length + ' trên ' + data.length + ' khách', adjAmt: st.adjAmt, adjWhy: st.adjWhy, adjMsg: st.adjMsg, onAmt: (e) => this.setState({ adjAmt: e.target.value }), onWhy: (e) => this.setState({ adjWhy: e.target.value }), onPlus: () => this.adjust(1), onMinus: () => this.adjust(-1), onLock: () => this.lock(), resetPassword: st.resetPassword, resetType: st.resetShown ? 'text' : 'password', resetVisibilityLabel: st.resetShown ? '\u1ea8n m\u1eadt kh\u1ea9u' : 'Hi\u1ec7n m\u1eadt kh\u1ea9u', onResetPassword: () => this.resetCustomerPassword(), onResetValue: (e) => this.setState({ resetPassword: e.target.value, adjMsg: '' }), onToggleReset: () => this.setState({ resetShown: !this.state.resetShown }) };
}
}
